 function sessionExpiry(tokenValue){
  try {
   const raw=tokenValue.split('.')[0].replace(/-/g,'+').replace(/_/g,'/');
   const payload=JSON.parse(atob(raw));
   return Number(payload.exp)*1000 || 0;
  } catch { return 0; }
 }
 function expireSession(){
