 async function readApiResponse(response){
  // An expired session is an authentication problem, not an inventory or Sheets failure.
  if(response.status===401){expireSession();throw Error('Session expired. Sign in again.');}
  const raw=await response.text();let parsed;
  try{parsed=raw?JSON.parse(raw):{}}catch{
   throw Error(`Server returned HTTP ${response.status} instead of JSON. Check Render logs for the underlying error.`);
  }
  if(!response.ok){const detail=parsed?.detail;throw Error(typeof detail==='string'?detail:detail?.message||`Request failed (HTTP ${response.status})`)}
  return parsed;
 }
 async function api(path,opts={}){
  const currentToken=token;
  if(!currentToken)throw Error('Login required');
  const expires=sessionExpiry(currentToken);
  if(expires && Date.now()>=expires){expireSession();throw Error('Session expired. Sign in again.');}
  const r=await fetch(path,{...opts,headers:{Authorization:`Bearer ${currentToken}`,'Content-Type':'application/json',...(opts.headers||{})}});
  // Ignore stale 401s from an earlier session after a new login.
  if(r.status===401 && token!==currentToken)throw Error('Previous session expired');
  return readApiResponse(r);
 }
