 async function execute(){if(!selected||busy)return;busy=true;error='';notice='';try{let data=await api(`/api/did/${selected.action}`,{method:'POST',body:JSON.stringify({did:selected.did,agent:selected.agent||null})});dids=dids.map(d=>d.did===selected.did?{...d,status:selected.action==='activate'?'active':'inactive'}:d);notice=`${selected.did}: ${selected.action} request accepted by MCube. Verify live status.`;selected=null;}catch(e){error=e.message}finally{busy=false}}
 function normalizeAgentPhone(value){const digits=String(value||'').replace(/\D/g,'');return digits.length===10?digits:(digits.length===12&&digits.startsWith('91')?digits.slice(2):(digits.length===13&&digits.startsWith('091')?digits.slice(3):''))}
 function exportCSV(){let cols=type==='active'?['did','agent','agent_number','email','operator','status'].filter(c=>({did:columnVisible.number,agent:columnVisible.agent,agent_number:columnVisible.phone,email:columnVisible.email,operator:columnVisible.operator,status:columnVisible.status})[c]):['did','operator','status'];let lines=[cols.join(','),...filtered.map(d=>cols.map(c=>'"'+String(c==='email'?(employeeEmails[normalizeAgentPhone(d.agent_number)]||''):(d[c]??'')).replaceAll('"','""')+'"').join(','))];let a=document.createElement('a');let u=URL.createObjectURL(new Blob(['\uFEFF'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}));a.href=u;a.download=`mcube-dids-${type}.csv`;a.click();URL.revokeObjectURL(u)}
</script>
<svelte:head><title>UNext SupportHub | DID Manager</title><meta name="description" content="MCube DID management workspace"/></svelte:head>
{#if !token}
 <main class="login auth-layout">
  <aside class="auth-hero" aria-label="UNext SupportHub welcome">
   <div class="auth-hero-pattern" aria-hidden="true"><span></span><span></span><span></span><span></span></div>
   <div class="auth-hero-content">
    <div class="auth-simple-icons auth-journey-header" aria-hidden="true"><span class="auth-spark">✳</span></div>
    <div class="support-film" role="img" aria-label="Animated journey: a student enquires about a course; a counsellor calls and guides them; the student starts an application, reports a problem; the counsellor raises a ticket; the support team resolves it.">
      <svg viewBox="0 0 600 265" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
        <g fill="none" stroke="white" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round">
          <path opacity=".35" d="M12 216 H588"/>
          <!-- Student: youthful hairstyle, backpack strap and mobile phone -->
          <g class="film-character film-student">
            <circle cx="99" cy="93" r="25"/>
            <path d="M74 87 Q79 62 96 66 L105 60 L109 69 Q122 70 123 87 M89 100 Q99 108 109 99"/>
            <path d="M57 210 V159 Q57 134 83 134 H113 Q141 134 141 159 V210 M85 137 L99 154 L112 137 M69 151 L77 209"/>
            <path class="film-student-hand" d="M140 168 Q155 153 162 137"/>
            <rect x="153" y="115" width="19" height="34" rx="4"/><path d="M160 142 H165"/>
          </g>
          <!-- Counsellor: headset, microphone and desktop computer -->
          <g class="film-character film-counsellor">
            <circle cx="300" cy="91" r="24"/>
            <path d="M275 90 Q275 57 300 57 Q325 57 325 90 M275 90 V106 Q275 113 284 113 M325 90 V106 Q325 113 316 113 M316 113 Q312 120 304 120"/>
            <path d="M260 210 V160 Q260 135 287 135 H313 Q340 135 340 160 V210 M286 138 L300 154 L314 138"/>
            <path d="M248 211 H353"/><rect x="326" y="170" width="49" height="35" rx="4"/>
            <path class="film-agent-hand" d="M340 178 Q355 165 365 177"/>
          </g>
          <!-- Support engineer: distinct glasses, laptop and keyboard -->
          <g class="film-character film-support">
            <circle cx="507" cy="92" r="25"/>
            <path d="M482 86 Q485 60 505 63 Q526 62 532 86 M487 96 H499 M513 96 H525 M499 96 H513 M499 105 Q508 111 517 105"/>
            <path d="M464 211 V161 Q464 135 490 135 H520 Q548 135 548 161 V211 M490 139 L507 155 L522 139"/>
            <path d="M450 212 H564"/><path d="M473 176 H545 L539 208 H478 Z M471 209 H547"/>
            <path class="film-support-hand" d="M467 177 Q480 186 487 185"/>
          </g>
          <!-- Six consecutive scenes: only the relevant communication moves -->
          <g class="film-scene film-enquiry"><rect x="111" y="25" width="94" height="45" rx="9"/><path d="M126 40 H190 M126 51 H176"/><path d="M137 70 L130 79 L129 70"/></g>
          <g class="film-scene film-call"><path class="film-link" d="M161 40 Q231 7 277 42" stroke-dasharray="7 9"/><path d="M202 41 Q207 34 213 41 M223 40 Q228 34 234 40"/><path class="film-pulse" d="M171 52 Q179 43 187 52"/></g>
          <g class="film-scene film-apply"><rect x="149" y="35" width="75" height="93" rx="7"/><path d="M161 53 H211 M161 65 H204 M161 77 H209 M162 97 L173 108 L207 83"/></g>
          <g class="film-scene film-issue"><path d="M165 31 H225 Q232 31 232 38 V76 Q232 83 225 83 H201 L188 95 V83 H165 Q158 83 158 76 V38 Q158 31 165 31Z"/><path d="M195 44 V62 M195 72 V73" stroke-width="4"/><path class="film-link" d="M234 49 Q265 29 282 49" stroke-dasharray="6 8"/></g>
          <g class="film-scene film-ticket"><rect class="film-moving-ticket" x="351" y="43" width="61" height="65" rx="6"/><path class="film-moving-ticket" d="M362 58 H401 M362 72 H400 M362 86 H390"/><path class="film-link" d="M369 30 Q426 5 471 39" stroke-dasharray="6 9"/></g>
          <g class="film-scene film-resolved"><rect x="393" y="33" width="60" height="60" rx="10"/><path class="film-check" d="M404 63 L419 77 L443 48"/><path class="film-link" d="M453 43 Q477 19 491 39" stroke-dasharray="6 9"/></g>
        </g>
        <g fill="white" font-family="Arial, sans-serif" text-anchor="middle">
          <g font-size="14" font-weight="600"><text x="99" y="244">Student</text><text x="300" y="244">Counsellor</text><text x="507" y="244">Support team</text></g>
          <g font-size="13" class="film-labels"><text class="film-scene film-enquiry" x="300" y="19">Course enquiry</text><text class="film-scene film-call" x="300" y="19">Counsellor calls and guides</text><text class="film-scene film-apply" x="300" y="19">Student starts application</text><text class="film-scene film-issue" x="300" y="19">Student reports an issue</text><text class="film-scene film-ticket" x="300" y="19">Counsellor raises a ticket</text><text class="film-scene film-resolved" x="300" y="19">Support resolves the issue</text></g>
        </g>
      </svg>
    </div>
    <h1>Hello, UNext! <span class="auth-wave" aria-hidden="true">👋</span></h1>
    <p>Connecting counsellors, students and support teams—from enrolment to resolution.</p>
   </div>
   <div class="auth-hero-footer">© {new Date().getFullYear()} UNext SupportHub. All rights reserved.</div>
  </aside>
  <section class="auth-form-side">
   <div class="auth-form-wrap">
    <div class="auth-wordmark"><img class="unext-logo" src="https://store.u-next.com/cdn/shop/files/UNEXT_Updated_LOGO.jpg?v=1765438884&amp;width=500" alt="UNext"/><span>SupportHub</span></div>
    <form class="login-card auth-card" onsubmit={e=>{e.preventDefault();challengeId?verifyOtp():signin()}}>
     <div class="auth-form-heading">
      {#if challengeId}
       <button type="button" class="auth-back" aria-label="Back to sign in" onclick={()=>{challengeId='';loginOtp='';otpExpiresAt=0;loginError=''}}><ArrowLeft size={17}/> Back to sign in</button>
       
       <h2>Verify your email</h2>
       <p>Enter the 6-digit code sent to <strong>{loginEmail}</strong>. Code expires in {Math.floor(otpRemaining/60)}:{String(otpRemaining%60).padStart(2,'0')}.</p>
      {:else}
       <h2>Welcome back!</h2>
       <p>Sign in securely to your operations workspace. <a href="/support-request" target="_blank" rel="noopener" class="public-request-link">Raise a support request</a></p>
      {/if}
     </div>
     {#if !challengeId}
      <div class="auth-field"><label for="auth-email">Work email</label><div class="auth-input-wrap"><Mail size={19}/><input id="auth-email" type="email" bind:value={loginEmail} placeholder="name@company.com" required autocomplete="username"/></div></div>
      <div class="auth-field"><label for="auth-pin">Security PIN</label><div class="auth-input-wrap"><LockKeyhole size={19}/><input id="auth-pin" type={showLoginPin?'text':'password'} inputmode="numeric" minlength="4" maxlength="12" bind:value={loginPin} placeholder="Enter your PIN" required autocomplete="current-password"/><button type="button" class="auth-eye" aria-label={showLoginPin?'Hide PIN':'Show PIN'} onclick={()=>showLoginPin=!showLoginPin}>{#if showLoginPin}<EyeOff size={18}/>{:else}<Eye size={18}/>{/if}</button></div></div>
     {:else}
      <div class="auth-field"><label for="auth-otp-0">Verification code</label><div class="otp-digits" onpaste={otpPaste} role="group" aria-label="Six digit email verification code">{#each Array.from({length:6},(_,i)=>i) as i}<input id={`auth-otp-${i}`} aria-label={`Digit ${i+1}`} type="text" inputmode="numeric" pattern="[0-9]*" maxlength="6" value={loginOtp[i]||''} oninput={(event)=>otpInput(event,i)} onkeydown={(event)=>otpKeydown(event,i)} autocomplete={i===0?'one-time-code':'off'} disabled={loginBusy||otpRemaining===0} />{/each}</div><p class="otp-help">Paste your 6-digit code or type it. Verification starts automatically.</p></div>
     {/if}
     {#if loginError}<div class="auth-error" role="alert"><AlertCircle size={17}/><span>{loginError}</span></div>{/if}
     <button class="auth-submit" disabled={loginBusy||(!!challengeId&&otpRemaining===0)} type="submit">{#if loginBusy}<RefreshCw size={18} class="spin"/>{:else}<span>{challengeId?'Verify code':'Continue securely'}</span><ArrowRight size={19}/>{/if}</button>
     
    </form>
   </div>
  </section>
 </main>
{:else}
 <div class="app"><header class="topbar"><div class="brand"><img class="unext-logo" src="https://store.u-next.com/cdn/shop/files/UNEXT_Updated_LOGO.jpg?v=1765438884&amp;width=500" alt="UNext"/><span>SupportHub</span></div><nav>{#each [{name:'Dashboard',icon:LayoutDashboard},{name:'Request',icon:FilePlus2},{name:'Analytics',icon:ChartNoAxesColumn},{name:'Report',icon:FileText},...(role==='admin'?[{name:'Settings',icon:Settings2}]:[])] as n}<button class:current={tab===n.name} disabled={batchBusy} onclick={()=>openTab(n.name)}><n.icon size={18}/>{n.name}</button>{/each}</nav><div class="account-inline" aria-label="Signed-in account"><span class="account-inline-avatar" aria-hidden="true"><UserRound size={21}/><i class="online-dot"></i></span><div class="account-inline-meta"><strong>{role==='admin'?'Administrator':'Operator'}</strong><small title={accountEmail}>{accountEmail||'Signed in'}</small><small class="account-sync" title="Last successful DID inventory sync"><span class="account-sync-dot"></span> Last sync: {inventoryStatus?.last_sync_utc?formatIST(inventoryStatus.last_sync_utc):'Not yet synced'}</small></div><button type="button" class="account-inline-logout" title="Sign out" aria-label="Sign out" disabled={batchBusy} onclick={signout}><LogOut size={19}/></button></div></header>
 <main class="container">
 {#if error}<div class="message error"><AlertCircle size={17}/>{error}<button onclick={()=>error=''}><X size={16}/></button></div>{/if}
 {#if toastError}<div class="workspace-toast workspace-toast-error" role="alert"><AlertCircle size={18}/><span>{toastError}</span><button aria-label="Dismiss error" onclick={()=>toastError=''}><X size={16}/></button></div>{/if}
 {#if notice}<div class="workspace-toast" role="status" aria-live="polite"><CheckCircle2 size={19}/><span>{notice}</span><button aria-label="Dismiss notification" onclick={()=>notice=''}><X size={17}/></button></div>{/if}

 {#if tab==='Dashboard'}
 {#if inventoryStatus && !inventoryStatus.initialized && tab==='Dashboard'}
 <section class="setup-banner"><div><strong>First-time setup: DID inventory has not been imported</strong><p>Your Google Sheet is empty. Import active, inactive and pool DIDs from the provider before using the replacement queue. This only reads DID and saves inventory snapshots; it does not replace DIDs or initiate calls.</p></div><button class="primary" disabled={loading||initialSyncBusy||batchBusy} onclick={initializeInventory}>{initialSyncBusy?'Importing inventory…':'Import MCube DID inventory'}</button></section>
{:else if inventoryStatus?.initialized && tab==='Dashboard'}
{/if}
<div class="did-workspace">
 <aside class="did-stats-column" aria-label="DID statistics"><div class="stats-unified-card"><h2>DID overview</h2><p>Current inventory</p><div class="stats-unified-list">
  <div class="did-stat-card"><span class="stat-symbol" aria-hidden="true">◈</span><span>Total DIDs</span><strong>{categoryItems.length.toLocaleString()}</strong></div>
  <div class="did-stat-card"><span class="stat-symbol" aria-hidden="true">♙</span><span>Assigned</span><strong>{counsellors.toLocaleString()}</strong></div>
  <div class="did-stat-card"><span class="stat-symbol" aria-hidden="true">▦</span><span>Common pool</span><strong>{activeCommonPool.toLocaleString()}</strong></div>
  <div class="did-stat-card"><span class="stat-symbol" aria-hidden="true">✓</span><span>Available Pool</span><strong>{pool.length.toLocaleString()}</strong></div>
 </div></div></aside>
 <section class="did-workspace-main" aria-label="DID inventory workspace">
  <div class="did-combined-toolbar">
  <div class="did-inline-filters did-workspace-filters">{#if filterVisible.search}<label class="input-icon"><Search size={18}/><input aria-label="Search DID inventory" bind:value={query} oninput={()=>page=1} placeholder="Search DID, agent, phone or email"/></label>{/if}{#if filterVisible.status}<select aria-label="DID status" bind:value={type} onchange={()=>{page=1;assignment='assigned';operator='all';selectedDids=[]}}><option value="active">Active DIDs</option><option value="inactive">Inactive DIDs</option><option value="pool">Available Pool</option></select>{/if}{#if type==='active' && filterVisible.assignment}<select aria-label="Assignment filter" bind:value={assignment} onchange={()=>page=1}><option value="all">All assignments</option><option value="assigned">Assigned</option><option value="unassigned">Unassigned</option></select>{/if}{#if type==='active' && filterVisible.operator}<select aria-label="Operator filter" bind:value={operator} onchange={()=>page=1}><option value="all">All operators</option>{#each operators as o}<option value={o}>{o}</option>{/each}</select>{/if}</div>
  <div class="did-top-actions"><div class="did-workspace-buttons"><button class="outline icon-operation" title="Refresh inventory" aria-label="Refresh inventory" onclick={()=>refresh(true)} disabled={loading||batchBusy}><RefreshCw size={17}/></button><button class="outline icon-operation" title="Download visible columns as CSV" aria-label="Download CSV" onclick={exportCSV}><Download size={17}/></button><button class="outline icon-operation" title="Choose visible columns" aria-label="Column visibility" onclick={()=>columnPickerOpen=true}><Columns3 size={17}/></button></div></div>
  </div>
  {#if type==='active'}<div class="did-workspace-selection"><span><b>{selectedDids.length} selected</b> · {pool.length} available in pool</span><div class="did-workspace-buttons">{#if duplicateGroups.length}<button class="duplicate-trigger" aria-expanded={showDuplicates} title="Review duplicate DID numbers in a dialog" onclick={()=>showDuplicates=!showDuplicates}><AlertCircle size={16}/> {duplicateGroups.length} duplicates</button>{/if}<button class="outline icon-operation" disabled={batchBusy} onclick={selectAllEligible} title="Select eligible DIDs up to available pool capacity" aria-label="Select eligible DIDs"><CheckCircle2 size={17}/></button><button class="outline icon-operation" disabled={batchBusy||!selectedDids.length} onclick={()=>selectedDids=[]} title="Clear selected DIDs" aria-label="Clear selected DIDs"><X size={17}/></button><button class="primary" disabled={batchBusy||!selectedDids.length||selectedDids.length>pool.length} onclick={()=>confirmBatch=true}>Reassign selected ({selectedDids.length})</button></div></div>{/if}

  <div class="did-table-viewport"><table><thead><tr>{#if type==='active'}<th class="check-col"><input aria-label="Select or unselect current page" type="checkbox" checked={allPageSelected} disabled={batchBusy} onchange={selectVisible}/></th>{/if}<th class="sl-col">#</th>{#if columnVisible.number}<th>DID NUMBER</th>{/if}{#if type==='active' && columnVisible.agent}<th>AGENT NAME</th>{/if}{#if type==='active' && columnVisible.phone}<th>AGENT NUMBER</th>{/if}{#if type==='active' && columnVisible.email}<th>EMAIL</th>{/if}{#if columnVisible.operator}<th>OPERATOR</th>{/if}{#if columnVisible.status}<th>STATUS</th>{/if}{#if type==='active' && columnVisible.action}<th class="action-col">ACTION</th>{/if}</tr></thead><tbody>{#each pageItems as d,i (`${d.status}-${d.did}-${(page-1)*inventoryPageSize+i}`)}<tr class:duplicate-row={d.duplicate}>{#if type==='active'}<td class="check-col">{#if d.agent_number && !d.duplicate && d.agent?.toLowerCase()!=='common pool'}<input type="checkbox" checked={selectedDids.includes(d.did)} disabled={batchBusy||(!selectedDids.includes(d.did)&&selectedDids.length>=pool.length)} onchange={()=>toggleDid(d.did)}/>{/if}</td>{/if}<td class="sl-col">{(page-1)*inventoryPageSize+i+1}</td>{#if columnVisible.number}<td class="number">{d.did}{#if d.duplicate}<span class="duplicate-label" title="Repeated DID">Duplicate</span>{/if}</td>{/if}{#if type==='active' && columnVisible.agent}<td class="agent-col">{#if d.agent_number}<button class="agent-name-link" title="View agent details" onclick={()=>openAgentProfile(d)}>{d.agent||'Unknown agent'} <ArrowRight size={13}/></button>{:else}{d.agent||'—'}{/if}</td>{/if}{#if type==='active' && columnVisible.phone}<td>{d.agent_number||'—'}</td>{/if}{#if type==='active' && columnVisible.email}<td class="email-cell">{#if employeeEmails[normalizeAgentPhone(d.agent_number)]}<span title={employeeEmails[normalizeAgentPhone(d.agent_number)]}>{employeeEmails[normalizeAgentPhone(d.agent_number)]}</span>{:else if d.agent_number && d.agent?.toLowerCase()!=='common pool'}<span class="missing-agent-email" title={emailLookupStatus==='failed'?'Employee directory lookup unavailable':`No email matched for agent_number ${d.agent_number}`}>{emailLookupStatus==='failed'?'Lookup unavailable':'Email missing'}</span>{:else}—{/if}</td>{/if}{#if columnVisible.operator}<td class="operator-col" title={d.operator||''}>{d.operator||'—'}</td>{/if}{#if columnVisible.status}<td><span class="pill {d.status==='active'?(d.agent_number&&d.agent?.toLowerCase()!=='common pool'?'counsellor':'commonpool'):d.status}">{d.status==='active'?(d.agent_number&&d.agent?.toLowerCase()!=='common pool'?'Counsellors':'Common pool'):d.status==='pool'?'Pool':'Inactive'}</span></td>{/if}{#if type==='active' && columnVisible.action}<td class="action-col">{#if d.agent_number && !d.duplicate && d.agent?.toLowerCase()!=='common pool'}<button class="action reassign-btn" title="Reassign DID" aria-label={`Reassign DID ${d.did}`} disabled={batchBusy} onclick={()=>openSingle(d)}><RefreshCw size={15}/> <span>Reassign</span></button>{/if}</td>{/if}</tr>{:else}<tr><td colspan="10" class="empty">{loading?'Loading…':'No DID records found.'}</td></tr>{/each}</tbody></table></div>
  <div class="pagination did-workspace-pagination"><span>Rows <select aria-label="DIDs per page" bind:value={inventoryPageSize} onchange={()=>page=1}><option value={5}>5</option><option value={10}>10</option><option value={25}>25</option><option value={50}>50</option><option value={100}>100</option></select> · {filtered.length?((page-1)*inventoryPageSize+1):0}–{Math.min(page*inventoryPageSize,filtered.length)} of {filtered.length}</span><div><button class="outline" disabled={page===1} onclick={()=>page--}>Previous</button><span>Page {page} of {Math.max(1,Math.ceil(filtered.length/inventoryPageSize))}</span><button class="outline" disabled={page*inventoryPageSize>=filtered.length} onclick={()=>page++}>Next</button></div></div>
 </section>
</div>
 {#if showDuplicates && duplicateGroups.length}<div class="dialog-backdrop" role="presentation" onclick={(e)=>{if(e.target===e.currentTarget)showDuplicates=false}}><section class="did-dialog" role="dialog" aria-modal="true" aria-label="Duplicate DID details"><header><div><h2>Duplicate DID numbers</h2><p>{duplicateGroups.length} repeated DID assignments require review before replacement.</p></div><button class="icon-operation outline" title="Close duplicate details" aria-label="Close duplicate details" onclick={()=>showDuplicates=false}><X size={19}/></button></header><div class="did-dialog-scroll"><table><thead><tr><th>Category</th><th>DID number</th><th>Occurrences</th><th>Agent(s)</th></tr></thead><tbody>{#each duplicateGroups as item}<tr><td>{item.status}</td><td><b>{item.did}</b></td><td>{item.count}</td><td>{item.agents||'—'}</td></tr>{/each}</tbody></table></div><footer><button class="outline" onclick={()=>showDuplicates=false}>Close</button></footer></section></div>{/if}
 {#if columnPickerOpen}<div class="dialog-backdrop" role="presentation" onclick={(e)=>{if(e.target===e.currentTarget)columnPickerOpen=false}}><section class="did-dialog column-dialog" role="dialog" aria-modal="true" aria-label="Choose visible columns"><header><div><h2>Column visibility</h2><p>Choose table columns and which filters appear in the toolbar.</p></div><button class="outline icon-operation" aria-label="Close column selection" title="Close" onclick={()=>columnPickerOpen=false}><X size={19}/></button></header><div class="did-dialog-scroll"><label class="column-toggle"><input type="checkbox" checked={Object.values(columnVisible).every(Boolean)} onchange={e=>columnVisible=Object.fromEntries(Object.keys(columnVisible).map(k=>[k,e.currentTarget.checked]))}/> Toggle all</label><div class="column-choices">{#each [{key:'number',label:'DID number'},{key:'agent',label:'Agent name'},{key:'phone',label:'Agent number'},{key:'email',label:'Email'},{key:'operator',label:'Operator'},{key:'status',label:'Status'},{key:'action',label:'Reassign action'}] as col}<label class="column-toggle"><input type="checkbox" checked={columnVisible[col.key]} onchange={e=>columnVisible={...columnVisible,[col.key]:e.currentTarget.checked}}/>{col.label}</label>{/each}</div><h3 class="picker-section-title">Visible filters</h3><div class="column-choices">{#each [{key:'search',label:'Search'},{key:'status',label:'DID status'},{key:'assignment',label:'Assignment'},{key:'operator',label:'Operator'}] as f}<label class="column-toggle"><input type="checkbox" checked={filterVisible[f.key]} onchange={e=>filterVisible={...filterVisible,[f.key]:e.currentTarget.checked}}/>{f.label}</label>{/each}</div></div><footer><button class="outline" onclick={()=>columnVisible={number:true,agent:true,phone:true,email:true,operator:true,status:true,action:true}}>Reset</button><button class="primary" onclick={()=>columnPickerOpen=false}>Done</button></footer></section></div>{/if}
 {#if batchBusy}<div class="message success">Bulk reassignment running: {batch?.done||0} / {batch?.total||selectedDids.length}. Navigation and DID controls are locked until processing finishes. Keep this tab open.</div>{/if}
 {#if batchError}<div class="message error">{batchError}</div>{/if}
 {#if batch?.error}<div class="message error">Batch stopped: {batch.error}. Review Change_Logs before retrying.</div>{/if}
 {#if operationResults.length}<div class="operation-results"><b>Replacement results</b>{#each operationResults as result}<div class:result-failed={result.status!=='success'}><span>{result.old} → {result.new||'—'}</span><span class="pill {result.status==='success'?'pool':'inactive'}">{result.status==='success'?'Completed':result.status==='failed'?`Failed: ${result.stage||'operation'} · review required`:'Stopped · reconcile'}</span><small>{result.reason||''}</small></div>{/each}</div>{/if}
 {:else if tab==='Request'}
 <div class="request-workspace"><aside class="request-stat-column"><div class="stats-unified-card"><h2>Request overview</h2><p>Queue at a glance</p><div class="metrics request-metrics"><div class="metric"><span>Pending / Approved</span><strong>{requests.filter(r=>['pending','approved'].includes(r.status)).length}</strong></div><div class="metric"><span>Recent repeat review</span><strong>{requests.filter(r=>r.status==='review_required').length}</strong></div><div class="metric"><span>Completed</span><strong>{requests.filter(r=>r.status==='completed').length}</strong></div><div class="metric"><span>Needs reconciliation</span><strong>{requests.filter(r=>r.status==='needs_reconciliation').length}</strong></div></div></div></aside><section class="request-queue-column"> <section class="request-toolbar"><div class="request-toolbar-label"><span class="toolbar-icon"><FilePlus2 size={20}/></span><div><h2>Request queue</h2><p>Track and act on incoming replacement requests</p></div></div><div class="request-toolbar-actions"><button class="primary" disabled={requestBusy||batchBusy} onclick={syncRequests}><RefreshCw size={16}/> {requestBusy?'Syncing…':'Sync calls'}</button><button class="outline" disabled={requestBusy||batchBusy} onclick={runReminders}>Check reminders</button><button class="outline" onclick={loadRequests}><RefreshCw size={16}/> Refresh</button></div></section>
 <div class="grid-tools"><button class="primary request-bulk-top" title="Replace selected requests" disabled={batchBusy||!chosenRequests.length} onclick={()=>requestConfirm=true}>Replace selected ({chosenRequests.length})</button>{#if requestFilterVisible.search}<div class="grid-search"><Search size={17}/><input aria-label="Search requests" placeholder="Search agent, mobile, DID or status…" bind:value={requestSearch} oninput={()=>requestPage=1}/></div>{/if}{#if requestFilterVisible.status}<select aria-label="Filter request status" bind:value={requestStatus} onchange={()=>requestPage=1}><option value="all">All statuses</option><option value="pending">Pending</option><option value="approved">Approved</option><option value="review_required">Review required</option><option value="completed">Completed</option><option value="rejected">Rejected</option><option value="needs_reconciliation">Needs reconciliation</option></select>{/if}<button class="outline icon-operation" title="Choose request columns and filters" aria-label="Request column visibility" onclick={()=>requestColumnPickerOpen=true}><Columns3 size={17}/></button><span>{requestFiltered.length} matching</span></div>
 <div class="table-card"><div class="table-scroll"><table><thead><tr><th title="Select request">✓</th>{#if requestColumnVisible.agent}<th>Agent</th>{/if}{#if requestColumnVisible.mobile}<th>Mobile</th>{/if}{#if requestColumnVisible.did}<th>Current DID</th>{/if}{#if requestColumnVisible.first}<th>First call</th>{/if}{#if requestColumnVisible.last}<th>Last call</th>{/if}{#if requestColumnVisible.calls}<th>Calls</th>{/if}{#if requestColumnVisible.status}<th>Status</th>{/if}{#if requestColumnVisible.action}<th>Action</th>{/if}</tr></thead><tbody>{#each requestVisible as r (r.request_id)}<tr><td><input type="checkbox" disabled={batchBusy||!['pending','approved'].includes(r.status)} checked={chosenRequests.includes(r.request_id)} onchange={()=>chosenRequests=chosenRequests.includes(r.request_id)?chosenRequests.filter(x=>x!==r.request_id):[...chosenRequests,r.request_id]}/></td>{#if requestColumnVisible.agent}<td>{r.agent_name||'—'}</td>{/if}{#if requestColumnVisible.mobile}<td>{r.agent_number}</td>{/if}{#if requestColumnVisible.did}<td>{r.current_did}</td>{/if}{#if requestColumnVisible.first}<td>{formatIST(r.first_call_utc)}</td>{/if}{#if requestColumnVisible.last}<td>{formatIST(r.last_call_utc)}</td>{/if}{#if requestColumnVisible.calls}<td>{r.call_count}</td>{/if}{#if requestColumnVisible.status}<td><span class="pill {r.status==='completed'?'active':r.recent_warning==='yes'?'inactive':'pool'}">{r.status}{r.recent_warning==='yes'?' · recent replacement':''}</span></td>{/if}{#if requestColumnVisible.action}<td>{#if ['pending','review_required'].includes(r.status)}<button class="action danger" disabled={batchBusy||requestBusy} onclick={()=>openReview(r,false)}>Reject</button>{/if}{#if ['pending','approved'].includes(r.status)}<button class="action reassign-btn" disabled={batchBusy||requestBusy} onclick={()=>{chosenRequests=[r.request_id];requestConfirm=true}}>Replace</button>{/if}</td>{/if}</tr>{:else}<tr><td colspan="9">No requests yet. Sync inbound calls to import qualifying requests.</td></tr>{/each}</tbody></table></div><div class="pagination"><span>Rows <select aria-label="Requests per page" bind:value={requestPageSize} onchange={()=>requestPage=1}><option value={5}>5</option><option value={10}>10</option><option value={25}>25</option><option value={50}>50</option><option value={100}>100</option></select> · Showing {requestFiltered.length?(requestPage-1)*requestPageSize+1:0}–{Math.min(requestPage*requestPageSize,requestFiltered.length)} of {requestFiltered.length}</span><div><button class="outline" disabled={requestPage===1} onclick={()=>requestPage--}>Previous</button><span>Page {requestPage} of {Math.max(1,Math.ceil(requestFiltered.length/requestPageSize))}</span><button class="outline" disabled={requestPage*requestPageSize>=requestFiltered.length} onclick={()=>requestPage++}>Next</button></div></div></div>
</section></div>
 {#if batchBusy}<div class="message success">Sequential replacement running. Do not initiate another batch.</div>{/if}
 {#if batchError}<div class="message error">{batchError}</div>{/if}
 {:else if tab==='Settings'}
 <div class="settings-header"><div><span class="settings-save-status">{settingsDirty?'Unsaved changes':'Settings saved in Google Sheets'}</span></div><div class="settings-actions">{#if role==='admin'}<button class="outline" disabled={batchBusy||loading} onclick={initializeInventory}><RefreshCw size={15}/> Sync inventory</button><button class="outline danger-outline" disabled={batchBusy||loading} onclick={clearInventorySnapshots}>Clear inventory snapshots</button>{/if}<button class="outline" disabled={saving} onclick={loadSettings}>Reload from Sheets</button>{#if role==='admin'}<button class="primary" disabled={saving||batchBusy||!settingsLoaded||!settingsDirty} onclick={saveSettings}>{saving?'Saving and verifying…':'Save changes'}</button>{/if}</div></div>
 {#if role!=='admin'}<div class="message error">Settings are read-only for operators.</div>{/if}
 {#if !settingsLoaded}<div class="message error">Settings have not loaded successfully. Do not edit or save until Google Sheets is accessible.</div>{/if}
 {#if settingsDirty}<div class="unsaved-indicator">You have unsaved changes. Reload discards them.</div>{/if}
 <div class="settings-workspace">
 <nav class="settings-nav" aria-label="Settings categories">
 {#each [{id:'intake',label:'Request intake'},{id:'credentials',label:'Provider login'},{id:'notifications',label:'Call notifications'},{id:'safety',label:'Replacement rules'},{id:'email',label:'Email'},{id:'employees',label:'Employee directory'},{id:'advanced',label:'Advanced'}] as section}
 <button type="button" class:active={settingsSection===section.id} onclick={()=>settingsSection=section.id}>{section.label}</button>
 {/each}
 </nav>
 <div class="settings-layout">
  {#if settingsSection==='credentials' && role==='admin'}<section class="settings-section"><div class="section-heading"><h2>MCube config portal login</h2><p>For inbound call logs and employee directory only. DID listing and replacement continue using the fixed REST bearer token.</p></div><div class="settings-fields"><label class="setting-field"><span>MCube username</span><input type="text" autocomplete="off" bind:value={mcubeUsername} placeholder="MCube portal username"/></label><label class="setting-field"><span>MCube password</span><input type="password" autocomplete="new-password" bind:value={mcubePassword} placeholder="Enter password to update"/></label></div><p>{mcubeCredentialConfigured?'Credentials saved (encrypted). Password is never displayed.':'Credentials not yet saved.'}</p>{#if mcubeCredentialMessage}<p aria-live="polite">{mcubeCredentialMessage}</p>{/if}<div class="settings-actions"><button class="primary" disabled={mcubeCredentialBusy||!mcubeUsername||!mcubePassword} onclick={saveMCubeCredentials}>{mcubeCredentialBusy?'Please wait…':'Save Provider login'}</button><button class="outline" disabled={mcubeCredentialBusy||!mcubeCredentialConfigured} onclick={testMCubeCredentials}>Test Provider login</button></div></section>{/if}
  {#if settingsSection==='intake'}<section class="settings-section"><div class="section-heading"><h2>DID and request intake</h2><p>Numbers and call-log import behavior</p></div><div class="settings-fields">
  {#each [{key:'request_did',label:'Replacement request DID',hint:'Editable provider filter-inbound DID; defaults to 8071439545 for new installations. Saved in Google Sheets.'},{key:'call_page_size',label:'Call-log page size',numeric:true,min:1},{key:'employee_refresh_hours',label:'Legacy employee refresh interval (hours)',numeric:true,min:1},{key:'auto_inventory_minutes',label:'Automatic DID inventory refresh (minutes)',numeric:true,min:1},{key:'auto_calls_minutes',label:'Automatic request-call sync (minutes)',numeric:true,min:1},{key:'auto_employee_minutes',label:'Automatic employee directory sync (minutes)',numeric:true,min:1},{key:'request_sync_lookback_minutes',label:'Call sync lookback (minutes)',numeric:true,min:1},{key:'recent_replacement_days',label:'Recent replacement warning (days)',numeric:true,min:1}] as field}<label class="setting-field"><span>{field.label}</span><input disabled={role!=='admin'||!settingsLoaded} type={field.numeric?'number':'text'} min={field.min} value={settings[field.key]??''} oninput={e=>changeSetting(field.key,field.numeric?Number(e.currentTarget.value):e.currentTarget.value)}/>{#if field.hint}<small>{field.hint}</small>{/if}</label>{/each}
  <label class="setting-field"><span>Request synchronization</span><select disabled={role!=='admin'||!settingsLoaded} value={settings.sync_mode||'manual'} onchange={e=>changeSetting('sync_mode',e.currentTarget.value)}><option value="manual">Manual only</option><option value="login">On application login</option></select></label>
  </div><p class="settings-help">Automatic sync runs when your external scheduler calls /api/maintenance/tick with MAINTENANCE_TOKEN. Configure cron-job.org every 5 minutes; each operation runs only when its saved interval is due. Reminders follow their existing settings. No browser needs to remain open.</p></section>{/if}
  {#if settingsSection==='safety'}<section class="settings-section"><div class="section-heading"><h2>Replacement safety</h2><p>Protect agents against accidental repeat replacements</p></div><div class="settings-toggle-list"><label class="setting-toggle"><input type="checkbox" disabled={role!=='admin'||!settingsLoaded} checked={!!settings.require_recent_review} onchange={e=>changeSetting('require_recent_review',e.currentTarget.checked)}/><span><b>Administrator review for recent replacements</b><small>Require approval for replacements within the configured warning period.</small></span></label></div></section>
  {/if}
  {#if settingsSection==='notifications'}<section class="settings-section"><div class="section-heading"><h2>Outbound call notifications</h2><p>The provider connects exenumber first, then custnumber. Level 1/2 numbers are saved in Google Sheets. Agent calls always use the verified provider agent number as exenumber. Leave calling disabled until tested.</p></div><div class="settings-fields">
  {#each [{key:'level1_exenumber',label:'Level 1 exenumber (provider registered agent mobile)'},{key:'level1_custnumber',label:'Level 1 custnumber (destination)'},{key:'level2_exenumber',label:'Level 2 exenumber (provider registered agent mobile)'},{key:'level2_custnumber',label:'Level 2 custnumber (destination)'},{key:'agent_notification_custnumber',label:'Agent notification custnumber (defaults to request DID)'},{key:'reminder_first_minutes',label:'First reminder delay (minutes)',numeric:true},{key:'reminder_interval_minutes',label:'Repeat interval (minutes)',numeric:true},{key:'reminder_escalation_minutes',label:'Escalation delay (minutes)',numeric:true},{key:'reminder_max_attempts',label:'Maximum attempts',numeric:true}] as field}<label class="setting-field"><span>{field.label}</span><input disabled={role!=='admin'||!settingsLoaded} type={field.numeric?'number':'text'} min={field.numeric?0:undefined} value={settings[field.key]??''} oninput={e=>changeSetting(field.key,field.numeric?Number(e.currentTarget.value):e.currentTarget.value)}/></label>{/each}
  </div><div class="settings-toggle-list">{#each [{key:'reminder_enabled',label:'Enable periodic reminder calls'},{key:'notify_on_queue',label:'Call Level 1 on new queue entry'},{key:'notify_level2_on_queue',label:'Also call Level 2 on new queue entry'},{key:'notify_on_completion',label:'Call agent after replacement (agent mobile as exenumber)'}] as field}<label class="setting-toggle"><input type="checkbox" disabled={role!=='admin'||!settingsLoaded} checked={!!settings[field.key]} onchange={e=>changeSetting(field.key,e.currentTarget.checked)}/><span><b>{field.label}</b></span></label>{/each}</div></section>
  {/if}
  {#if settingsSection==='email'}<section class="settings-section"><div class="section-heading"><h2>Email and Brevo</h2><p>Brevo credentials remain private in Render environment variables</p></div><div class="settings-fields">{#each [{key:'admin_email',label:'Administrator notification email'},{key:'mail_from',label:'Notification sender address'}] as field}<label class="setting-field"><span>{field.label}</span><input disabled={role!=='admin'||!settingsLoaded} type="email" value={settings[field.key]??''} oninput={e=>changeSetting(field.key,e.currentTarget.value)}/></label>{/each}<label class="setting-field"><span>Mail provider</span><select disabled={role!=='admin'||!settingsLoaded} value={settings.mail_provider||'disabled'} onchange={e=>changeSetting('mail_provider',e.currentTarget.value)}><option value="disabled">Disabled</option><option value="brevo">Brevo API</option></select></label></div><div class="settings-toggle-list">{#each [{key:'email_on_queue',label:'Email agent when queued'},{key:'email_on_completion',label:'Email agent when completed'}] as field}<label class="setting-toggle"><input type="checkbox" disabled={role!=='admin'||!settingsLoaded} checked={!!settings[field.key]} onchange={e=>changeSetting(field.key,e.currentTarget.checked)}/><span><b>{field.label}</b></span></label>{/each}</div></section>
  {/if}
  {#if settingsSection==='employees'}<section class="settings-section"><div class="section-heading"><h2>Employee directory</h2><p>Import minimal employee fields for request matching and email notifications</p></div><button class="outline" disabled={employeeSyncBusy||batchBusy} onclick={syncEmployees}>{employeeSyncBusy?'Refreshing employees…':'Refresh employee directory'}</button></section>{/if}
 {#if settingsSection==='advanced'}<section class="settings-section"><div class="section-heading"><h2>Advanced routing</h2><p>Legacy fallback numbers, saved in Google Sheets.</p></div><div class="settings-fields">{#each [{key:'first_contact_number',label:'Legacy first contact'},{key:'second_contact_number',label:'Legacy second contact'},{key:'outbound_caller_number',label:'Legacy outbound caller'}] as field}<label class="setting-field"><span>{field.label}</span><input type="tel" disabled={role!=='admin'||!settingsLoaded} value={settings[field.key]??''} oninput={e=>changeSetting(field.key,e.currentTarget.value)}/></label>{/each}</div><p class="settings-help">Keep infrastructure secrets in Render environment variables, not GitHub or Google Sheets.</p></section>{/if}
 </div></div>
 
 {:else if tab==='Analytics' || tab==='Report'}
 <section class="insights-page">
  <div class="insights-heading"><div><h2>{tab==='Analytics'?'Overview':'Reports'}</h2><p>Saved requests, employee directory and verified DID operations</p></div><button class="outline" disabled={insightsBusy} onclick={loadInsights}><RefreshCw size={16}/>{insightsBusy?'Loading…':'Refresh data'}</button></div>
  {#if insightsError}<div class="message error">{insightsError}</div>{/if}
  {#if insights}
  <div class="insight-kpis">{#each [{name:'Employees',value:insights.summary.employees},{name:'Requests',value:insights.summary.requests},{name:'Repeat employees',value:insights.summary.repeat_requests},{name:'Avg. turnaround',value:insights.summary.average_turnaround_hours===null?'—':`${insights.summary.average_turnaround_hours}h`},{name:'Median turnaround',value:insights.summary.median_turnaround_hours===null?'—':`${insights.summary.median_turnaround_hours}h`},{name:'Verified replacements',value:insights.summary.replacement_completions},{name:'Inbound call events',value:insights.summary.call_events},{name:'Audit events',value:insights.summary.audit_events}] as k}<div class="insight-kpi"><span>{k.name}</span><strong>{k.value.toLocaleString()}</strong></div>{/each}</div>
  {#if tab==='Analytics'}
  <div class="insight-grid"><section class="insight-panel"><h2>Request status</h2><p>Current workflow distribution</p>{#each Object.entries(insights.statuses).sort((a,b)=>b[1]-a[1]) as item}<div class="bar-row"><div><b>{item[0].replaceAll('_',' ')}</b><span>{item[1]}</span></div><div class="bar-track"><div class="bar-fill" style:width={`${100*item[1]/Math.max(1,insights.summary.requests)}%`}></div></div></div>{:else}<p>No requests recorded yet.</p>{/each}</section><section class="insight-panel"><h2>Requests over time</h2><p>Daily volume, based on first call date</p><div class="daily-bars">{#each insights.by_day.slice(-21) as day}<div class="daily-col" title={`${day.date}: ${day.requests} requests`}><span style:height={`${Math.max(4,100*day.requests/Math.max(1,...insights.by_day.map(x=>x.requests)))}%`}></span><small>{day.date.slice(5)}</small></div>{:else}<p>No daily activity yet.</p>{/each}</div></section></div>
  {/if}
  <section class="insight-panel"><div class="insight-section-heading"><div><h2>Monthly employee replacement requests</h2><p>One count per distinct request, not per inbound call. Filter by month or employee.</p></div><button class="outline" disabled={!monthlyAgents.length} onclick={()=>downloadReport(filteredMonthly,'monthly-employee-requests.csv')}><Download size={16}/> Export CSV</button></div><div class="grid-tools"><div class="grid-search"><Search size={17}/><input placeholder="Search agent, phone, manager or TL" bind:value={analyticsSearch} oninput={()=>analyticsPage=1}/></div><select bind:value={analyticsMonth} onchange={()=>analyticsPage=1}><option value="all">All months</option>{#each [...new Set(monthOptions)].sort().reverse() as month}<option value={month}>{month}</option>{/each}</select><select aria-label="Filter monthly operation" bind:value={analyticsOperation} onchange={()=>analyticsPage=1}><option value="all">All operations</option><option value="requests">Requests</option><option value="calls">Inbound calls</option><option value="completed">Completed</option><option value="rejected">Rejected</option></select><select aria-label="Monthly rows per page" bind:value={analyticsPageSize} onchange={()=>analyticsPage=1}><option value={10}>10 rows</option><option value={25}>25 rows</option><option value={50}>50 rows</option><option value={100}>100 rows</option></select></div><div class="table-scroll"><table><thead><tr><th>Month</th><th>Employee</th><th>Mobile</th><th>Manager</th><th>Team lead</th><th>Requests</th><th>Inbound calls</th><th>Completed</th><th>Rejected</th></tr></thead><tbody>{#each filteredMonthly.slice((analyticsPage-1)*analyticsPageSize,analyticsPage*analyticsPageSize) as a}<tr><td>{a.month}</td><td><strong>{a.agent_name||'Unknown'}</strong></td><td>{a.agent_number}</td><td>{a.manager||'—'}</td><td>{a.team_lead||'—'}</td><td><strong>{a.requests}</strong></td><td>{a.calls}</td><td>{a.completed}</td><td>{a.rejected}</td></tr>{:else}<tr><td colspan="9">No matching monthly requests.</td></tr>{/each}</tbody></table></div><div class="pagination"><span>{filteredMonthly.length} records</span><div><button class="outline" disabled={analyticsPage===1} onclick={()=>analyticsPage--}>Previous</button><span>Page {analyticsPage} of {Math.max(1,Math.ceil(filteredMonthly.length/analyticsPageSize))}</span><button class="outline" disabled={analyticsPage*analyticsPageSize>=filteredMonthly.length} onclick={()=>analyticsPage++}>Next</button></div></div></section>
  <section class="insight-panel"><div class="insight-section-heading"><div><h2>Manager and team lead performance</h2><p>Requests grouped by provider role5 (manager) and role4 (team lead)</p></div><button class="outline" onclick={()=>downloadReport(filteredTeams,'manager-teamlead-report.csv')} disabled={!insights.teams.length}><Download size={16}/> Export CSV</button></div><div class="grid-tools analytics-filters"><div class="grid-search"><Search size={17}/><input aria-label="Search manager or team lead" placeholder="Search manager or team lead" bind:value={teamSearch}/></div><select aria-label="Manager performance month" bind:value={teamMonth}><option value="all">All months</option>{#each [...new Set(monthOptions)].sort().reverse() as month}<option value={month}>{month}</option>{/each}</select><select aria-label="Manager performance operation" bind:value={teamOperation}><option value="all">All operations</option><option value="requests">Requests</option><option value="repeat_calls">Repeat calls</option><option value="pending">Pending</option><option value="completed">Completed</option></select></div><div class="table-scroll"><table><thead><tr><th>Manager</th><th>Team lead</th><th>Employees</th><th>Requests</th><th>Repeat calls</th><th>Pending</th><th>Review</th><th>Completed</th><th>Repeat employees</th><th>Avg. resolution</th><th>Completion %</th></tr></thead><tbody>{#each filteredTeams as t}<tr><td>{t.manager}</td><td>{t.team_lead}</td><td>{t.unique_employees}</td><td><strong>{t.requests}</strong></td><td>{t.repeat_calls}</td><td>{t.pending}</td><td>{t.review_required}</td><td>{t.completed}</td><td>{t.repeat_employee_count}</td><td>{t.average_turnaround_hours===null?'—':`${t.average_turnaround_hours}h`}</td><td>{t.completion_rate_pct}%</td></tr>{:else}<tr><td colspan="11">No requests available for reporting.</td></tr>{/each}</tbody></table></div></section>
  <section class="insight-panel"><div class="insight-section-heading"><div><h2>Employee request frequency</h2><p>Identify frequent requests and repeated calls</p></div><button class="outline" onclick={()=>downloadReport(filteredAgents,'employee-request-frequency.csv')} disabled={!insights.agents.length}><Download size={16}/> Export CSV</button></div><div class="grid-tools analytics-filters"><div class="grid-search"><Search size={17}/><input aria-label="Search employee, manager or team lead" placeholder="Search employee, manager or team lead" bind:value={reportSearch} oninput={()=>employeePage=1}/></div><select aria-label="Employee request month" bind:value={employeeMonth} onchange={()=>employeePage=1}><option value="all">All months</option>{#each [...new Set(monthOptions)].sort().reverse() as month}<option value={month}>{month}</option>{/each}</select><select aria-label="Employee operation" bind:value={employeeOperation} onchange={()=>employeePage=1}><option value="all">All operations</option><option value="requests">Requests</option><option value="calls">Calls</option><option value="completed">Completed</option></select><select aria-label="Employee rows per page" bind:value={employeePageSize} onchange={()=>employeePage=1}><option value={10}>10 rows</option><option value={25}>25 rows</option><option value={50}>50 rows</option><option value={100}>100 rows</option></select></div><div class="table-scroll"><table><thead><tr><th>Employee</th><th>Mobile</th><th>Team lead</th><th>Manager</th><th>Requests</th><th>Calls</th><th>Completed</th><th>Median gap</th><th>Avg. resolution</th><th>Last replacement</th><th>Last request</th></tr></thead><tbody>{#each filteredAgents.slice((employeePage-1)*employeePageSize,employeePage*employeePageSize) as a}<tr><td><button class="agent-name-link" onclick={()=>openAgentProfile({agent:a.agent_name,agent_number:a.agent_number,did:dids.find(d=>d.agent_number===a.agent_number)?.did||'',operator:dids.find(d=>d.agent_number===a.agent_number)?.operator||''})}>{a.agent_name||'Unknown'} <ArrowRight size={13}/></button></td><td>{a.agent_number}</td><td>{a.team_lead||'—'}</td><td>{a.manager||'—'}</td><td>{a.requests}</td><td>{a.calls}</td><td>{a.completed}</td><td>{a.median_days_between_requests===null?'—':`${a.median_days_between_requests}d`}</td><td>{a.average_turnaround_hours===null?'—':`${a.average_turnaround_hours}h`}</td><td>{a.last_replacement_utc?formatIST(a.last_replacement_utc):'—'}</td><td>{a.last_request_utc?formatIST(a.last_request_utc):'—'}</td></tr>{:else}<tr><td colspan="11">No matching employees.</td></tr>{/each}</tbody></table></div><div class="pagination"><span>{filteredAgents.length} employees</span><div><button class="outline" disabled={employeePage===1} onclick={()=>employeePage--}>Previous</button><span>Page {employeePage} of {Math.max(1,Math.ceil(filteredAgents.length/employeePageSize))}</span><button class="outline" disabled={employeePage*employeePageSize>=filteredAgents.length} onclick={()=>employeePage++}>Next</button></div></div></section>
  <section class="insight-method"><strong>QC measurement rules</strong><span>Turnaround: first qualifying call → verified completion. Repeat requests: separate requests for the same employee; multiple cancelled calls within one request are tracked separately. Manager/TL reflects the current directory. Last call is not treated as a DID replacement.</span><small>{insights.summary.turnaround_sample_size} completed requests have valid turnaround timestamps.</small></section>
  {#if tab==='Report'}<section class="insight-panel"><div class="insight-section-heading"><div><h2>Recent DID operations</h2><p>Recorded audit events; only verified completion events count as successful replacements</p></div><button class="outline" onclick={()=>downloadReport(insights.recent_operations,'did-operation-audit.csv')} disabled={!insights.recent_operations.length}><Download size={16}/> Export CSV</button></div><div class="table-scroll"><table><thead><tr><th>Time</th><th>Event</th><th>Agent</th><th>Old DID</th><th>New DID</th><th>Result</th></tr></thead><tbody>{#each insights.recent_operations as e}<tr><td>{formatIST(e.time_utc)}</td><td>{e.event}</td><td>{e.agent_name||e.agent_number||'—'}</td><td>{e.old_did||'—'}</td><td>{e.new_did||'—'}</td><td>{e.result||'—'}</td></tr>{:else}<tr><td colspan="6">No audit history yet.</td></tr>{/each}</tbody></table></div></section>{/if}
  {:else if insightsBusy}<p>Loading saved operational data…</p>{/if}
 </section>
 {:else}<div class="placeholder"><h1>{tab}</h1><button class="outline" onclick={()=>tab='Dashboard'}>Back to Dashboard</button></div>{/if}
 </main></div>
{/if}
{#if agentProfile}
 <div class="agent-full-page">
  <div class="agent-page-top"><button class="outline" onclick={closeAgentProfile}><ArrowLeft size={17}/> Back to {profileReturnTab}</button><span class="agent-page-kicker">AGENT DETAILS / VERIFIED HISTORY</span></div>
  <div class="agent-page-heading"><span class="agent-avatar agent-avatar-large">{(agentProfile.agent||'A').charAt(0).toUpperCase()}</span><div><h1>{agentProfileData?.employee?.agent_name||agentProfile.agent||'Agent details'}</h1><p>{agentProfile.agent_number} · Individual DID assignment and request history</p></div><button class="outline" disabled={agentProfileLoading} onclick={()=>openAgentProfile(agentProfile)}><RefreshCw size={16}/> Refresh</button></div>
  {#if agentProfileLoading}<div class="agent-content-card">Loading agent records from Google Sheets…</div>{:else if agentProfileError}<div class="agent-content-card error">{agentProfileError}</div>{:else if agentProfileData}
   <div class="agent-detail-stats"><div class="summary-tile peach"><span>Current DID</span><strong>{dids.find(d=>d.agent_number===agentProfile.agent_number&&d.status==='active')?.did||agentProfile.did||'—'}</strong></div><div class="summary-tile mint"><span>Requests</span><strong>{agentProfileData.request_count}</strong></div><div class="summary-tile sky"><span>Verified replacements</span><strong>{agentProfileData.replacement_count}</strong></div><div class="summary-tile lavender"><span>Last replacement</span><strong class="agent-stat-date">{agentProfileData.replacements[0]?formatIST(agentProfileData.replacements[0].completed_at_ist):'—'}</strong></div></div>
   <div class="agent-detail-columns"><section class="agent-content-card"><h2>Agent information</h2><dl class="agent-info-grid"><dt>Agent number</dt><dd>{agentProfile.agent_number}</dd><dt>Email</dt><dd>{agentProfileData.employee.email||'—'}</dd><dt>Team lead</dt><dd>{agentProfileData.employee.role4||'—'}</dd><dt>Manager</dt><dd>{agentProfileData.employee.role5||'—'}</dd><dt>Operator</dt><dd>{agentProfile.operator||'—'}</dd><dt>Role</dt><dd>{agentProfileData.employee.role||'—'}</dd></dl></section><section class="agent-content-card"><h2>Activity summary</h2><p>Completed DID replacements are verified against the provider and recorded in the Google Sheets change journal.</p><div class="agent-info-grid"><span>Total requests</span><b>{agentProfileData.request_count}</b><span>Verified changes</span><b>{agentProfileData.replacement_count}</b><span>Latest call</span><b>{agentProfileData.requests[0]?formatIST(agentProfileData.requests[0].last_call_utc):'—'}</b></div></section></div>
   <section class="agent-content-card"><h2>DID replacement timeline</h2><p>Verified completion time, previous DID, replacement DID and batch identifier.</p><div class="agent-history-table"><table><thead><tr><th>Completed (IST)</th><th>Previous DID</th><th>New DID</th><th>Batch</th><th>Status</th></tr></thead><tbody>{#each agentProfileData.replacements as h}<tr><td>{formatIST(h.completed_at_ist)}</td><td>{h.old_did||'—'}</td><td><strong>{h.new_did||'—'}</strong></td><td>{h.batch_id||'—'}</td><td><span class="pill counsellor">Verified</span></td></tr>{:else}<tr><td colspan="5" class="empty">No verified replacements recorded yet.</td></tr>{/each}</tbody></table></div></section>
   <section class="agent-content-card"><h2>Request history</h2><div class="agent-history-table"><table><thead><tr><th>First call (IST)</th><th>Last call (IST)</th><th>DID</th><th>Calls</th><th>Status</th><th>Completion (IST)</th></tr></thead><tbody>{#each agentProfileData.requests as r}<tr><td>{formatIST(r.first_call_utc)}</td><td>{formatIST(r.last_call_utc)}</td><td>{r.current_did||'—'}</td><td>{r.call_count||0}</td><td>{r.status||'Pending'}</td><td>{formatIST(r.completed_utc)}</td></tr>{:else}<tr><td colspan="6" class="empty">No requests found for this agent.</td></tr>{/each}</tbody></table></div></section>
  {/if}
 </div>
{/if}
{#if reviewTarget}
 <div class="overlay" role="presentation" onclick={e=>{if(e.target===e.currentTarget&&!requestBusy)reviewTarget=null}}>
  <section class="modal single-modal" role="dialog" aria-modal="true" aria-label="Confirm request review">
   <button class="close" disabled={requestBusy} onclick={()=>reviewTarget=null}><X size={20}/></button>
   <h2>{reviewDecision?'Approve':'Reject'} replacement request?</h2>
   <p class="subtitle">This changes the request status only. It does not call MCube or replace a DID.</p>
   <div class="detail"><h3>REQUEST DETAILS</h3><div class="detail-grid"><span>Agent</span><b>{reviewTarget.agent_name||'—'}</b><span>Mobile</span><b>{reviewTarget.agent_number}</b><span>Current DID</span><b>{reviewTarget.current_did}</b><span>Calls</span><b>{reviewTarget.call_count}</b><span>Status</span><b>{reviewTarget.status}</b><span>Last call</span><b>{formatIST(reviewTarget.last_call_utc)}</b></div></div>
   <label class="date-field">Reason for {reviewDecision?'approval':'rejection'}<textarea rows="3" bind:value={reviewReason} placeholder="Enter reason" style="width:100%;min-height:76px;padding:12px;border:1px solid #ddd;border-radius:10px"></textarea></label>
   <div class="modal-actions"><button class="outline" disabled={requestBusy} onclick={()=>reviewTarget=null}>Cancel</button><button class:danger={!reviewDecision} class="primary" disabled={requestBusy||!reviewReason.trim()} onclick={confirmReview}>{requestBusy?'Saving…':reviewDecision?'Confirm approval':'Confirm rejection'}</button></div>
  </section>
 </div>
{/if}
{#if requestColumnPickerOpen}<div class="dialog-backdrop" role="presentation" onclick={e=>{if(e.target===e.currentTarget)requestColumnPickerOpen=false}}><section class="did-dialog column-dialog" role="dialog" aria-modal="true" aria-label="Request table settings"><header><div><h2>Request table preferences</h2><p>Choose columns and filters shown in the request queue.</p></div><button class="outline icon-operation" title="Close" aria-label="Close" onclick={()=>requestColumnPickerOpen=false}><X size={18}/></button></header><div class="did-dialog-scroll"><h3 class="picker-section-title">Columns</h3><div class="column-choices">{#each [{key:'agent',label:'Agent'},{key:'mobile',label:'Mobile'},{key:'did',label:'Current DID'},{key:'first',label:'First call'},{key:'last',label:'Last call'},{key:'calls',label:'Calls'},{key:'status',label:'Status'},{key:'action',label:'Actions'}] as c}<label class="column-toggle"><input type="checkbox" checked={requestColumnVisible[c.key]} onchange={e=>requestColumnVisible={...requestColumnVisible,[c.key]:e.currentTarget.checked}}/>{c.label}</label>{/each}</div><h3 class="picker-section-title">Filters</h3><div class="column-choices">{#each [{key:'search',label:'Search'},{key:'status',label:'Status filter'}] as c}<label class="column-toggle"><input type="checkbox" checked={requestFilterVisible[c.key]} onchange={e=>requestFilterVisible={...requestFilterVisible,[c.key]:e.currentTarget.checked}}/>{c.label}</label>{/each}</div></div><footer><button class="primary" onclick={()=>requestColumnPickerOpen=false}>Done</button></footer></section></div>{/if}
{#if requestConfirm}
 <div class="overlay" role="presentation" onclick={e=>{if(e.target===e.currentTarget&&!batchBusy)requestConfirm=false}}>
  <section class="modal batch-modal" role="dialog" aria-modal="true" aria-label="Confirm request FIFO replacements">
   <button class="close" disabled={batchBusy} onclick={()=>requestConfirm=false}><X size={20}/></button>
   <h2>Confirm request replacements ({chosenRequests.length})</h2>
   <p class="subtitle">Review the requested replacements before starting sequential DID operations. The server revalidates the current assignment and available pool. This action can change live DIDs.</p>
   <div class="plan-scroll"><table class="plan-table"><thead><tr><th>Agent</th><th>Mobile</th><th>Current DID</th><th>Proposed available DID</th><th>New operator</th><th>Request status</th></tr></thead><tbody>
    {#each chosenRequests as id,i}{@const r=requests.find(item=>item.request_id===id)}{#if r}<tr><td>{r.agent_name||'—'}</td><td>{r.agent_number}</td><td>{r.current_did}</td><td>{pool[i]?.did||'Not loaded — server determines FIFO'}</td><td>{pool[i]?.operator||'—'}</td><td>{r.status}</td></tr>{/if}{/each}
   </tbody></table></div>
   <p class="safety-note">FIFO values are illustrative only; server-side live verification is authoritative. If an operation is uncertain, do not repeat it until reconciled.</p>
   <div class="modal-actions"><button class="outline" onclick={()=>requestConfirm=false}>Cancel</button><button class="primary" disabled={batchBusy||!chosenRequests.length} onclick={replaceRequests}>Confirm & start {chosenRequests.length} replacements</button></div>
  </section>
 </div>
{/if}
{#if confirmBatch}<div class="overlay" role="presentation" onclick={e=>{if(e.target===e.currentTarget&&!batchBusy)confirmBatch=false}}><section class="modal batch-modal" role="dialog" aria-modal="true" aria-label="Confirm bulk reassignment"><button class="close" disabled={batchBusy} onclick={()=>confirmBatch=false}><X size={20}/></button><h2>Confirm bulk reassignment ({selectedDids.length})</h2><p class="subtitle">One agent at a time, in selection order. Old DID deactivation is followed by new DID activation and verification. Preview assignments may change if the live pool changes.</p><label class="date-field">Replacement request date<input type="date" bind:value={date}/></label><div class="plan-scroll"><table class="plan-table"><thead><tr><th>Agent</th><th>Agent number</th><th>Current DID</th><th>Operator</th><th>Proposed available DID</th><th>New operator</th><th>Status</th></tr></thead><tbody>{#each batchPlan as row,i}<tr><td>{row.old?.agent||'—'}</td><td>{row.old?.agent_number||'—'}</td><td>{row.old?.did||'—'}</td><td>{row.old?.operator||'—'}</td><td>{row.next?.did||'Unavailable'}</td><td>{row.next?.operator||'—'}</td><td><span class="pill queued">Queued</span></td></tr>{/each}</tbody></table></div><p class="safety-note">If MCube rejects a deactivation, that record remains pending and the batch continues. Uncertain or partial changes stop the batch for administrator reconciliation.</p><div class="modal-actions"><button class="outline" onclick={()=>confirmBatch=false}>Cancel</button><button class="primary" disabled={batchBusy||selectedDids.length>pool.length} onclick={startBatch}>Deactivate & reassign {selectedDids.length}</button></div></section></div>{/if}
{#if selected && selected.action==='reassign'}
<div class="overlay" role="presentation" onclick={e=>{if(e.target===e.currentTarget&&!batchBusy)selected=null}}>
 <section class="modal single-modal compact-reassign-modal" role="dialog" aria-modal="true" aria-label="Reassign DID">
  <button class="close" disabled={batchBusy} aria-label="Close" onclick={()=>selected=null}><X size={19}/></button>
  <h2>Confirm DID reassignment</h2>
  <p class="subtitle">Review the current and proposed DID before proceeding.</p>
  <div class="compact-reassign-agent"><strong>{selected.agent||'Unknown agent'}</strong><span>{selected.agent_number||'—'}</span></div>
  <div class="compact-reassign-comparison">
   <div class="compact-reassign-side"><small>Current DID</small><strong>{selected.did}</strong><span>{selected.operator||'—'}</span></div>
   <div class="compact-reassign-arrow" aria-hidden="true">→</div>
   <div class="compact-reassign-side"><small>New available DID</small><strong>{pool[0]?.did||'Unavailable'}</strong><span>{pool[0]?.operator||'—'}</span></div>
  </div>
  <label class="compact-reassign-date">Request date <input type="date" bind:value={date}/></label>
  <p class="compact-reassign-notice">The live assignment and available pool are verified again before replacement.</p>
  <div class="modal-actions"><button class="outline" disabled={batchBusy} onclick={()=>selected=null}>Cancel</button><button class="primary" disabled={batchBusy||!pool.length} onclick={confirmSingle}>{batchBusy?'Processing…':'Approve & reassign'}</button></div>
 </section>
</div>{/if}
